alter table sales_document add column subsidiary_id int8 not null;
alter table sales_document add column currency_id int8 not null;
alter table sales_document add column exchange_rate numeric default 1 not null;
alter table sales_document add column fiscal_period_id int8 not null;
alter table sales_document add column location_id int8;
alter table sales_document add column payment_term_id int8;
alter table sales_document add column memo text;
alter table sales_document add column total_amount numeric default 0 not null;
alter table sales_document add column transaction_id int8;
alter table sales_document add column created_by int8;
alter table sales_document add column created_at timestamptz default now() not null;
alter table sales_document add column updated_at timestamptz default now() not null;
alter table sales_document alter column document_id set not null;alter table sales_document alter column document_id add generated always as identity;alter table sales_document add primary key(document_id);
create table sales_document_line(line_id int8 generated always as identity primary key not null,document_id int8 not null,line_number int4 not null,product_id int8 not null,account_id int8,description text,quantity numeric not null,unit_price numeric not null,tax_code_id int8,tax_rate numeric default 0 not null,tax_amount numeric default 0 not null,gross_amount numeric not null,department_id int8,cost_center_id int8,class_id int8,related_company_id int8,foreign key(document_id) references sales_document on delete cascade);
create table if not exists quotation(quote_id bigint generated always as identity primary key,quote_number text,transaction_id bigint,customer_id bigint,subsidiary_id bigint,total_amount numeric);
create table if not exists sales_order(so_id bigint generated always as identity primary key,so_number text,transaction_id bigint,customer_id bigint,subsidiary_id bigint,currency_id bigint,status_id bigint);
create table if not exists delivery(delivery_id bigint generated always as identity primary key,delivery_number text,transaction_id bigint,so_id bigint,location_id bigint,delivery_date date);
alter table subsidiary_currencies add column if not exists is_primary boolean default false;
